      map_star' := ?_ }
  intro z
  refine _root_.DirectLimit.induction (f := f) (fun n X => ?_) z
  rw [_root_.DirectLimit.star_def]
  change σ n (star X) = star (σ n X)
  exact map_star (σ n) X

